import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0]=='n':
        return None
    r = T(int(arr[0]))
    q = deque([r]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def diameter_best(root):
    def dfs(node):
        if node is None: return (-1, 0)
        lh, ld = dfs(node.l)
        rh, rd = dfs(node.r)
        return (max(lh, rh) + 1, max(ld, rd, lh + rh + 2))
    return dfs(root)[1]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1+n])
    print(diameter_best(root))
